#include <algorithm>
#include <fstream>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, a[3], b[3]; in >> n;
    for (int& x : a) in >> x;
    for (int& x : b) in >> x;
    auto close = [&](int x, int y) {
        int d = x > y ? x - y : y - x;
        return min(d, n - d) <= 2;
    };
    int count = 0;
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int z = 1; z <= n; ++z) {
                bool john = close(x,a[0]) && close(y,a[1]) && close(z,a[2]);
                bool master = close(x,b[0]) && close(y,b[1]) && close(z,b[2]);
                if (john || master) ++count;
            }
    out << count << '\n';
}
int main() {
    ifstream in("combo.in"); ofstream out("combo.out"); solve(in,out);
}
