#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; long long x,y,z; in >> n >> x >> y >> z;
    vector<pair<long long,long long>> events;
    for (int i=0; i<n; ++i) {
        long long a,b; in >> a >> b;
        events.push_back({a,y-x});
        events.push_back({b+1,z-y});
    }
    sort(events.begin(),events.end());
    long long milk=n*x, best=milk;
    for (size_t i=0; i<events.size();) {
        long long t=events[i].first, change=0;
        while (i<events.size() && events[i].first==t) change+=events[i++].second;
        milk+=change;
        best=max(best,milk);
    }
    out << best << '\n';
}
int main() {
    ifstream in("milktemp.in"); ofstream out("milktemp.out"); solve(in,out);
}
