#include <algorithm>
#include <fstream>
#include <string>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; long long k; in >> n >> k;
    vector<vector<string>> missing(n);
    for (int i=0; i<n; ++i) {
        string word;
        for (int j=0; j<4; ++j) in >> word;
        while (in >> word && word!="cow.") missing[i].push_back(word);
    }
    int length=static_cast<int>(missing[0].size());
    vector<vector<string>> words(length);
    for (int j=0; j<length; ++j) {
        for (const auto& row:missing) words[j].push_back(row[j]);
        sort(words[j].begin(),words[j].end());
        words[j].erase(unique(words[j].begin(),words[j].end()),words[j].end());
    }
    vector<long long> suffix(length+1,1);
    for (int j=length-1; j>=0; --j) suffix[j]=suffix[j+1]*words[j].size();
    vector<long long> absent;
    for (const auto& row:missing) {
        long long rank=0;
        for (int j=0; j<length; ++j)
            rank+=(lower_bound(words[j].begin(),words[j].end(),row[j])-words[j].begin())*suffix[j+1];
        absent.push_back(rank);
    }
    sort(absent.begin(),absent.end());
    absent.erase(unique(absent.begin(),absent.end()),absent.end());
    long long rank=k-1;
    for (long long forbidden:absent) {
        if (forbidden<=rank) ++rank;
        else break;
    }
    for (int j=0; j<length; ++j) {
        if (j) out << ' ';
        out << words[j][static_cast<size_t>(rank/suffix[j+1])];
        rank%=suffix[j+1];
    }
    out << '\n';
}
int main() {
    ifstream in("nocow.in"); ofstream out("nocow.out"); solve(in,out);
}
